// Package dbcore 提供数据库操作的核心功能
// 本文件实现SQL查询条件构建器，支持链式调用构建复杂查询条件
package dbcore

import (
	"fmt"
	"strings"
)

// ==================== 查询构建器 ====================

// QueryBuilder 查询条件构建器
// 提供链式API构建SQL WHERE条件，自动处理参数绑定
// 所有条件默认使用AND连接
//
// 使用示例:
//
//	query, args := dbcore.NewQueryBuilder().
//	    Like("name", "张").
//	    Eq("status", 1).
//	    Gte("age", 18).
//	    Build()
//	// query: "name LIKE ? AND status = ? AND age >= ?"
//	// args: ["%张%", 1, 18]
type QueryBuilder struct {
	conditions []string      // SQL条件片段列表
	args       []interface{} // 对应的参数列表
}

// NewQueryBuilder 创建查询构建器实例
func NewQueryBuilder() *QueryBuilder {
	return &QueryBuilder{
		conditions: make([]string, 0),
		args:       make([]interface{}, 0),
	}
}

// ==================== 模糊查询 ====================

// Like 模糊查询（包含匹配）: field LIKE '%value%'
func (q *QueryBuilder) Like(field string, value string) *QueryBuilder {
	if value != "" {
		q.conditions = append(q.conditions, fmt.Sprintf("%s LIKE ?", safeField(field)))
		q.args = append(q.args, "%"+value+"%")
	}
	return q
}

// LikeLeft 左模糊查询（以指定值结尾）: field LIKE '%value'
func (q *QueryBuilder) LikeLeft(field string, value string) *QueryBuilder {
	if value != "" {
		q.conditions = append(q.conditions, fmt.Sprintf("%s LIKE ?", safeField(field)))
		q.args = append(q.args, "%"+value)
	}
	return q
}

// LikeRight 右模糊查询（以指定值开头）: field LIKE 'value%'
// 推荐优先使用此方法替代 Like，可走索引
func (q *QueryBuilder) LikeRight(field string, value string) *QueryBuilder {
	if value != "" {
		q.conditions = append(q.conditions, fmt.Sprintf("%s LIKE ?", safeField(field)))
		q.args = append(q.args, value+"%")
	}
	return q
}

// ==================== 比较查询 ====================

// Eq 等于查询: field = value
// 注意: int/int64/float64 类型的 0 被视为有效值，不会被忽略
func (q *QueryBuilder) Eq(field string, value interface{}) *QueryBuilder {
	if !isEmpty(value) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s = ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// EqIfPositive 条件等于查询（仅当值 > 0 时生效）
// 使用场景: 查询参数中 0 表示"全部"，> 0 表示具体状态
func (q *QueryBuilder) EqIfPositive(field string, value int) *QueryBuilder {
	if value > 0 {
		q.conditions = append(q.conditions, fmt.Sprintf("%s = ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// Ne 不等于查询: field != value
func (q *QueryBuilder) Ne(field string, value interface{}) *QueryBuilder {
	if !isEmpty(value) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s != ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// Gt 大于查询: field > value
func (q *QueryBuilder) Gt(field string, value interface{}) *QueryBuilder {
	if !isEmpty(value) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s > ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// Gte 大于等于查询: field >= value
func (q *QueryBuilder) Gte(field string, value interface{}) *QueryBuilder {
	if !isEmpty(value) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s >= ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// Lt 小于查询: field < value
func (q *QueryBuilder) Lt(field string, value interface{}) *QueryBuilder {
	if !isEmpty(value) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s < ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// Lte 小于等于查询: field <= value
func (q *QueryBuilder) Lte(field string, value interface{}) *QueryBuilder {
	if !isEmpty(value) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s <= ?", safeField(field)))
		q.args = append(q.args, value)
	}
	return q
}

// Between 区间查询: field BETWEEN start AND end
// 注意: start 和 end 必须同时有效才会生成条件
func (q *QueryBuilder) Between(field string, start, end interface{}) *QueryBuilder {
	if !isEmpty(start) && !isEmpty(end) {
		q.conditions = append(q.conditions, fmt.Sprintf("%s BETWEEN ? AND ?", safeField(field)))
		q.args = append(q.args, start, end)
	}
	return q
}

// ==================== 范围查询 ====================

// In 范围查询（通用版本）: field IN (?, ?, ...)
func (q *QueryBuilder) In(field string, values []interface{}) *QueryBuilder {
	if len(values) > 0 {
		placeholders := make([]string, len(values))
		for i := range values {
			placeholders[i] = "?"
		}
		q.conditions = append(q.conditions,
			fmt.Sprintf("%s IN (%s)", safeField(field), strings.Join(placeholders, ",")))
		q.args = append(q.args, values...)
	}
	return q
}

// InStrings 字符串范围查询: field IN (?, ?, ...)
//
// 修复说明: 原版本在循环内追加 args 后才追加 condition，
// 导致多个链式条件时 args 与占位符顺序错位。
// 现改为先构建 placeholders 和 ifaces，再统一追加 condition 和 args。
func (q *QueryBuilder) InStrings(field string, values []string) *QueryBuilder {
	if len(values) > 0 {
		placeholders := make([]string, len(values))
		ifaces := make([]interface{}, len(values))
		for i, v := range values {
			placeholders[i] = "?"
			ifaces[i] = v
		}
		q.conditions = append(q.conditions,
			fmt.Sprintf("%s IN (%s)", safeField(field), strings.Join(placeholders, ",")))
		q.args = append(q.args, ifaces...)
	}
	return q
}

// InInts 整数范围查询: field IN (?, ?, ...)
//
// 修复说明: 同 InStrings，修复 args 追加顺序问题。
func (q *QueryBuilder) InInts(field string, values []int) *QueryBuilder {
	if len(values) > 0 {
		placeholders := make([]string, len(values))
		ifaces := make([]interface{}, len(values))
		for i, v := range values {
			placeholders[i] = "?"
			ifaces[i] = v
		}
		q.conditions = append(q.conditions,
			fmt.Sprintf("%s IN (%s)", safeField(field), strings.Join(placeholders, ",")))
		q.args = append(q.args, ifaces...)
	}
	return q
}

// NotIn 不在范围内查询: field NOT IN (?, ?, ...)
func (q *QueryBuilder) NotIn(field string, values []interface{}) *QueryBuilder {
	if len(values) > 0 {
		placeholders := make([]string, len(values))
		for i := range values {
			placeholders[i] = "?"
		}
		q.conditions = append(q.conditions,
			fmt.Sprintf("%s NOT IN (%s)", safeField(field), strings.Join(placeholders, ",")))
		q.args = append(q.args, values...)
	}
	return q
}

// NotLike 模糊排除查询: field NOT LIKE '%value%'
func (q *QueryBuilder) NotLike(field string, value string) *QueryBuilder {
	if value != "" {
		q.conditions = append(q.conditions, fmt.Sprintf("%s NOT LIKE ?", safeField(field)))
		q.args = append(q.args, "%"+value+"%")
	}
	return q
}

// ==================== NULL 查询 ====================

// IsNull 空值查询: field IS NULL
func (q *QueryBuilder) IsNull(field string) *QueryBuilder {
	q.conditions = append(q.conditions, fmt.Sprintf("%s IS NULL", safeField(field)))
	return q
}

// IsNotNull 非空值查询: field IS NOT NULL
func (q *QueryBuilder) IsNotNull(field string) *QueryBuilder {
	q.conditions = append(q.conditions, fmt.Sprintf("%s IS NOT NULL", safeField(field)))
	return q
}

// ==================== 自定义条件 ====================

// Raw 添加原始SQL条件，用于构建复杂条件（如子查询）
// 示例: Raw("(status = ? OR type = ?)", 1, 2)
func (q *QueryBuilder) Raw(condition string, args ...interface{}) *QueryBuilder {
	if condition != "" {
		q.conditions = append(q.conditions, condition)
		q.args = append(q.args, args...)
	}
	return q
}

// OrGroup 将多个子条件用 OR 连接后作为整体 AND 到主条件
// 示例:
//
//	qb.OrGroup(
//	    NewQueryBuilder().Eq("status", 1),
//	    NewQueryBuilder().Eq("status", 3),
//	)
//	// 生成: (status = ? OR status = ?)  args: [1, 3]
func (q *QueryBuilder) OrGroup(conditions ...*QueryBuilder) *QueryBuilder {
	parts := make([]string, 0, len(conditions))
	for _, c := range conditions {
		if c.IsEmpty() {
			continue
		}
		subQuery, subArgs := c.Build()
		parts = append(parts, "("+subQuery+")")
		q.args = append(q.args, subArgs...)
	}
	if len(parts) > 0 {
		q.conditions = append(q.conditions, "("+strings.Join(parts, " OR ")+")")
	}
	return q
}

// ==================== 构建方法 ====================

// IsEmpty 判断构建器是否没有任何条件
// 可用于调用方主动判断是否意外传入了空查询
func (q *QueryBuilder) IsEmpty() bool {
	return len(q.conditions) == 0
}

// Build 构建最终的查询条件
// 将所有条件用 AND 连接，返回完整的 WHERE 子句（不含 WHERE 关键字）
// 无条件时返回 "1=1"（恒真，避免空 WHERE 报错）
//
// 使用示例:
//
//	query, args := builder.Build()
//	db.Where(query, args...).Find(&list)
func (q *QueryBuilder) Build() (string, []interface{}) {
	if len(q.conditions) == 0 {
		return "1=1", nil
	}
	return strings.Join(q.conditions, " AND "), q.args
}

// BuildWithPrefix 构建带前缀的查询条件
// 无条件时不添加前缀，直接返回 "1=1"
func (q *QueryBuilder) BuildWithPrefix(prefix string) (string, []interface{}) {
	query, args := q.Build()
	if query == "1=1" {
		return query, args
	}
	return prefix + " " + query, args
}

// ==================== 辅助函数 ====================

// safeField 校验字段名，防止 SQL 注入
// 只允许字母、数字、下划线和点号（支持 table.column 格式）
func safeField(field string) string {
	for _, c := range field {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '_' || c == '.') {
			panic(fmt.Sprintf("dbcore: invalid field name %q (only [a-zA-Z0-9_.] allowed)", field))
		}
	}
	return field
}

// isEmpty 判断值是否为空（nil 或空字符串）
// int/int64/float64 类型的 0 视为有效值，返回 false
// 如需忽略 0 值，请使用 EqIfPositive
func isEmpty(value interface{}) bool {
	if value == nil {
		return true
	}
	switch v := value.(type) {
	case string:
		return v == ""
	default:
		return false
	}
}

// Package dbcore 提供数据库操作的核心功能
// 本文件实现事务管理功能，支持嵌套事务和事务传播
package dbcore

import (
	"context"

	"gorm.io/gorm"
)

// ==================== 类型定义 ====================

type (
	// Transaction 事务管理接口
	Transaction interface {
		ExecTx(context.Context, func(ctx context.Context) error) error
	}

	txDB struct {
		db *gorm.DB
	}

	// contextTxKey 事务上下文键，使用空结构体避免与其他包键冲突
	contextTxKey struct{}
)

// NewTransaction 创建事务管理器
//
// 使用示例:
//
//	tx := dbcore.NewTransaction(db)
//	err := tx.ExecTx(ctx, func(ctx context.Context) error {
//	    return userModel.Insert(ctx, user)
//	})
func NewTransaction(db *gorm.DB) Transaction {
	return &txDB{db: db}
}

// ExecTx 执行事务
//
// 支持嵌套调用，GORM 自动通过 SavePoint 实现嵌套事务：
//   - 业务函数返回 nil → 自动 COMMIT
//   - 业务函数返回 error / panic → 自动 ROLLBACK
//   - 嵌套调用 → 自动创建 SavePoint，支持局部回滚
//
// 使用示例:
//
//	// 基本事务
//	err := tx.ExecTx(ctx, func(ctx context.Context) error {
//	    if err := orderModel.Insert(ctx, order); err != nil {
//	        return err
//	    }
//	    return stockModel.Decrease(ctx, order.ProductID, order.Qty)
//	})
//
//	// 嵌套事务
//	err := tx.ExecTx(ctx, func(ctx context.Context) error {
//	    userModel.Insert(ctx, user)
//	    return tx.ExecTx(ctx, func(ctx context.Context) error {
//	        return logModel.Insert(ctx, log) // SavePoint 保护
//	    })
//	})
func (t *txDB) ExecTx(ctx context.Context, f func(ctx context.Context) error) error {
	// 已在事务中（嵌套场景）：复用现有事务，GORM 自动创建 SavePoint
	if tx, ok := ctx.Value(contextTxKey{}).(*gorm.DB); ok {
		return tx.Transaction(func(nestedTx *gorm.DB) error {
			return f(context.WithValue(ctx, contextTxKey{}, nestedTx))
		})
	}
	// 首次开启事务
	return t.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		return f(context.WithValue(ctx, contextTxKey{}, tx))
	})
}

// ==================== 辅助函数 ====================

// GetDB 获取数据库连接
//
// 优先从 ctx 中取事务连接（保证操作在同一事务内），
// 非事务时用 NewDB Session 创建干净会话，避免条件累积。
func GetDB(ctx context.Context, db *gorm.DB) *gorm.DB {
	if tx, ok := ctx.Value(contextTxKey{}).(*gorm.DB); ok {
		return tx
	}
	return db.Session(&gorm.Session{NewDB: true})
}

// InTransaction 判断当前是否在事务中
//
// 使用场景: 需要根据是否在事务中采取不同策略时
//
//	if dbcore.InTransaction(ctx) {
//	    return service.DoSomething(ctx)
//	} else {
//	    return tx.ExecTx(ctx, func(ctx context.Context) error {
//	        return service.DoSomething(ctx)
//	    })
//	}
func InTransaction(ctx context.Context) bool {
	_, ok := ctx.Value(contextTxKey{}).(*gorm.DB)
	return ok
}

# GORM v2 Association 关联操作

> GORM v2 的 Association 模式与 v1 差异很大，本文覆盖 v2 的正确用法。

---

## 1. 关联类型定义（v2 规范）

```go
// 禁止物理外键，所有关联字段只建索引（见 base-model-pattern.md §1）
type User struct {
    gorm.Model
    Name    string
    Orders  []Order  `gorm:"foreignKey:UserID;constraint:false"` // 一对多
    Profile *Profile `gorm:"foreignKey:UserID;constraint:false"` // 一对一
    Roles   []Role   `gorm:"many2many:user_roles;constraint:false"` // 多对多
}

type Order struct {
    gorm.Model
    UserID uint   `gorm:"not null;index"` // 逻辑外键：只加索引
    User   User   `gorm:"foreignKey:UserID;constraint:false"`
    Status string
}
```

---

## 2. Preload（预加载，避免 N+1）

```go
// 基础 Preload
db.Preload("Orders").Find(&users)
// SELECT * FROM users; SELECT * FROM orders WHERE user_id IN (1,2,3)

// 带条件的 Preload
db.Preload("Orders", "status = ?", "paid").Find(&users)

// 多级 Preload
db.Preload("Orders.Items").Find(&users)

// Preload 所有关联（v2 新增）
db.Preload(clause.Associations).Find(&users)

// 自定义 Preload 查询
db.Preload("Orders", func(db *gorm.DB) *gorm.DB {
    return db.Order("created_at DESC").Limit(5) // 每个用户只加载最近 5 个订单
}).Find(&users)
```

---

## 3. Joins 预加载（单次 SQL）

```go
// Joins 用 LEFT JOIN，适合需要按关联字段过滤的场景
db.Joins("Profile").Find(&users)
// SELECT users.*, profiles.* FROM users LEFT JOIN profiles ON profiles.user_id = users.id

// 带条件的 Joins
db.Joins("Profile", db.Where(&Profile{Active: true})).Find(&users)

// Joins + 过滤主表
db.Joins("JOIN orders ON orders.user_id = users.id AND orders.status = ?", "paid").
    Find(&users)
```

### Preload vs Joins 选择

| 场景 | 推荐 |
|------|------|
| 只是附带加载关联数据 | `Preload`（两次查询，内存友好） |
| 需要按关联字段过滤主表 | `Joins` |
| 关联数据量大（万级+） | `Preload` + 分页，或手动查询 |
| 多层嵌套关联 | `Preload("A.B.C")` |

---

## 4. Association 模式（操作关联数据）

```go
// 获取关联操作句柄
assoc := db.Model(&user).Association("Orders")

// Append：添加关联（不删除现有，适合多对多 / 一对多）
assoc.Append(&Order{Amount: 100}, &Order{Amount: 200})

// Replace：替换所有关联（删除旧关联，添加新的）
assoc.Replace(&Order{Amount: 300}) // user 只关联这一个 order

// Delete：移除指定关联（多对多时删除中间表记录）
assoc.Delete(&order1, &order2)

// Clear：清除所有关联
assoc.Clear()

// Count：统计关联数量
count := assoc.Count()

// Find：查询关联（带条件）
var paidOrders []Order
assoc.Find(&paidOrders, "status = ?", "paid")

// 错误处理
if err := assoc.Error; err != nil {
    log.Error(err)
}
```

---

## 5. Select + Omit 控制级联写入

```go
// Select：只保存指定的关联（其余关联不处理）
db.Select("Orders").Create(&userWithOrders)
// 只创建 user 和 Orders，忽略 Profile

// Select("*")：保存所有字段和关联
db.Select("*").Create(&user)

// Omit：排除指定关联
db.Omit("Profile").Create(&user)
// 创建 user，跳过 Profile 关联

// Omit(clause.Associations)：完全不处理任何关联（最常用）
db.Omit(clause.Associations).Create(&user)
// 只创建 user 本身，所有关联字段忽略

// 更新时同样适用
db.Session(&gorm.Session{FullSaveAssociations: true}).
    Omit("Orders").Save(&user) // 保存 user 和 Profile，跳过 Orders
```

---

## 6. FullSaveAssociations

```go
// 默认 false：Save 不级联保存关联
db.Save(&user) // 只保存 user 本身

// 开启后：Save 级联保存所有关联（注意性能）
db.Session(&gorm.Session{FullSaveAssociations: true}).Save(&user)
// 保存 user + user.Orders + user.Profile

// ⚠️ 生产环境慎用 FullSaveAssociations：
// 1. 可能触发大量 INSERT/UPDATE
// 2. 关联层级深时难以预测行为
// 推荐改为显式操作关联
```

---

## 7. 多对多关联管理

```go
type User struct {
    gorm.Model
    Roles []Role `gorm:"many2many:user_roles;constraint:false"`
}

type Role struct {
    gorm.Model
    Name string
}

// 添加角色（INSERT INTO user_roles）
db.Model(&user).Association("Roles").Append(&adminRole, &editorRole)

// 替换角色（DELETE 旧的 + INSERT 新的）
db.Model(&user).Association("Roles").Replace(&viewerRole)

// 移除角色（DELETE FROM user_roles WHERE user_id=? AND role_id=?）
db.Model(&user).Association("Roles").Delete(&adminRole)

// 自定义中间表字段
type UserRole struct {
    UserID    uint      `gorm:"primaryKey"`
    RoleID    uint      `gorm:"primaryKey"`
    CreatedAt time.Time // 中间表额外字段
    ExpiresAt time.Time
}
```

---

## 8. 关联数据的软删除处理

```go
// 软删除会自动过滤 deleted_at IS NOT NULL 的关联
// 如需包含软删除的关联数据：
db.Unscoped().Preload("Orders").Find(&users)

// 只查已软删除的关联
db.Preload("Orders", func(db *gorm.DB) *gorm.DB {
    return db.Unscoped().Where("deleted_at IS NOT NULL")
}).Find(&users)
```

---

## 9. 常见坑

| 坑 | 说明 | 解决 |
|----|------|------|
| Preload 忘加条件导致加载全量关联 | `Preload("Orders")` 无限制 | 加 Limit 或在 Preload func 内分页 |
| Association.Append 触发物理 FK 报错 | 有 FK 约束时 Append 可能失败 | 改用逻辑外键（`constraint:false`） |
| Save 意外级联更新 | `FullSaveAssociations` 全局开启 | 只在必要时 Session 级别开启 |
| 多对多 Replace 删除了不该删的记录 | Replace 会清除所有现有关联再重建 | 用 Append + Delete 精确控制 |
| N+1 在 AfterFind Hook 中触发 | Hook 内对每条记录做额外查询 | 改用 Preload 批量加载 |

# GORM 泛型 BaseModel 设计规范

> 本文档总结在实际项目（`dbcore.BaseModel[T]` 模式）中发现的常见 Bug、性能问题与最佳实践。

---

## 1. QueryBuilder —— args 顺序 Bug（高危）

### 问题

`InStrings` / `InInts` 在循环内边追加 `args` 边构建 `placeholders`，当有多个链式条件时，`args` 的追加顺序与 `conditions` 中占位符的顺序错位：

```go
// ❌ 错误写法：args 在循环内追加，condition 在循环外追加
func (q *QueryBuilder) InStrings(field string, values []string) *QueryBuilder {
    if len(values) > 0 {
        placeholders := make([]string, len(values))
        for i, v := range values {
            placeholders[i] = "?"
            q.args = append(q.args, v)   // ← 先追加 args
        }
        q.conditions = append(q.conditions, ...) // ← 后追加 condition
    }
}
// 对比 In() 是 q.args = append(q.args, values...) 在循环外统一追加
// 不一致导致：链式调用时 args 顺序与占位符不匹配，SQL 参数绑定出错
```

### 修复

```go
// ✅ 正确写法：先构建 placeholders 和 ifaces，再统一追加
func (q *QueryBuilder) InStrings(field string, values []string) *QueryBuilder {
    if len(values) > 0 {
        placeholders := make([]string, len(values))
        ifaces := make([]interface{}, len(values))
        for i, v := range values {
            placeholders[i] = "?"
            ifaces[i] = v
        }
        // condition 和 args 同步追加，顺序一致
        q.conditions = append(q.conditions,
            fmt.Sprintf("%s IN (%s)", field, strings.Join(placeholders, ",")))
        q.args = append(q.args, ifaces...)
    }
    return q
}
```

> `InInts` 同样有此问题，修复方式相同。

---

## 2. 软删除 + 唯一索引冲突

### 问题

`uniqueIndex` 不包含 `deleted_at` 时，软删除后该字段值仍占用唯一约束，重新创建相同值报 `Duplicate entry`：

```go
// ❌ 软删除后 order_no 仍占用唯一约束，同订单号无法重建
OrderNo    string         `gorm:"uniqueIndex"`
DeletedAt  gorm.DeletedAt `gorm:"index"`
```

### 修复

```go
// ✅ 复合唯一索引：order_no + deleted_at
// 软删除后 deleted_at = timestamp（非 NULL），不与新记录的 NULL 冲突
OrderNo    string         `gorm:"column:order_no;uniqueIndex:idx_order_no_del"`
DeletedAt  gorm.DeletedAt `gorm:"index;uniqueIndex:idx_order_no_del"`
```

> 原理：MySQL 唯一索引中多个 NULL 不冲突。软删除前 `deleted_at IS NULL`，软删除后 `deleted_at = 时间戳`，两者不相等，新记录可以正常插入。

---

## 3. AutoMigrate 生产环境风险

### 问题

```go
// ❌ 服务启动时执行 AutoMigrate，大表会锁表，影响线上服务
func NewOrderModel(db *gorm.DB, isMigrate bool) OrderModel {
    if isMigrate {
        db.AutoMigrate(&Order{})  // 100万行以上会触发 ALTER TABLE 锁表
    }
}
```

### 修复

```go
// ✅ 生产环境禁用 AutoMigrate，使用 golang-migrate 脚本管理迁移
func NewOrderModel(db *gorm.DB, isMigrate bool) OrderModel {
    if isMigrate {
        migrateDB := db.Session(&gorm.Session{})
        migrateDB.DisableForeignKeyConstraintWhenMigrating = true // 禁止物理 FK
        if err := migrateDB.AutoMigrate(&Order{}); err != nil {
            panic(err)
        }
    }
    // ...
}
```

**环境策略**：

| 环境 | isMigrate | 迁移方式 |
|------|-----------|----------|
| 本地开发 | `true` | AutoMigrate（快速迭代） |
| 测试环境 | `true` | AutoMigrate |
| 生产环境 | `false` | golang-migrate 脚本（详见 references/migration.md） |

---

## 4. Find() 应使用 Take() 而非 First()

### 问题

```go
// ❌ First() 会隐式追加 ORDER BY id，按主键查单条无需排序
func (m *BaseModel[T]) Find(ctx context.Context, id string) (*T, error) {
    m.GetTxDB(ctx).Where("id = ?", id).First(&v)
    // 实际执行: SELECT * FROM t WHERE id=? ORDER BY id LIMIT 1
}
```

### 修复

```go
// ✅ Take() 不追加 ORDER BY，语义更准确，略微减少排序开销
m.GetTxDB(ctx).Where("id = ?", id).Take(&v)
// 实际执行: SELECT * FROM t WHERE id=? LIMIT 1
```

| 方法 | 语义 | 隐式 ORDER BY |
|------|------|--------------|
| `First()` | 按主键升序取第一条 | `ORDER BY id ASC` |
| `Last()` | 按主键降序取第一条 | `ORDER BY id DESC` |
| `Take()` | 不排序取一条 | 无 |

