```go
// ❌ string 存 JSON：需手动 Marshal/Unmarshal，无法利用 MySQL JSON 函数查询
ExtData string `gorm:"column:ext_data;type:text"`

// ✅ datatypes.JSON：自动序列化，支持 JSONQuery
