const maxInSize = 1000

func (m *BaseModel[T]) DeleteByIds(ctx context.Context, ids []string) error {
    if len(ids) > maxInSize {
        return fmt.Errorf("dbcore: DeleteByIds count %d exceeds max %d", len(ids), maxInSize)
    }
    // ...
