```go
// ✅ 排除包含特定关键词的记录
qb := NewQueryBuilder().
    Eq("status", 1).
    NotLike("name", "测试")  // name NOT LIKE '%测试%'
query, args := qb.Build()
// query: "status = ? AND name NOT LIKE ?"
// args:  [1, "%测试%"]
