    for range ticker.C {
        sqlDB, _ := db.DB()
        stats := sqlDB.Stats()
        log.Info("db pool stats",
            "open", stats.OpenConnections,
            "in_use", stats.InUse,
            "idle", stats.Idle,
            "wait_count", stats.WaitCount,
            "wait_duration", stats.WaitDuration,
        )
    }
}()
