# GORM Raw SQL / Scan / Row 使用指南

## 何时用 Raw SQL

- 复杂聚合、窗口函数、GORM API 难以表达的 SQL
- 性能极度敏感的热路径（绕过 GORM 反射开销）
- 存储过程调用

## Raw + Scan

```go
// Scan 到自定义 struct（不需要是 Model）
type Result struct {
    UserID int64
    Total  int64
}
var results []Result
db.Raw(`
    SELECT user_id, SUM(amount) AS total
    FROM orders
    WHERE created_at >= ?
    GROUP BY user_id
    HAVING total > ?
`, time.Now().Add(-30*24*time.Hour), 1000).Scan(&results)

// 检查错误
if err := db.Error; err != nil {
    return err
}
```

## Exec（写操作）

```go
db.Exec("UPDATE orders SET status = ? WHERE expired_at < ?", "expired", time.Now())
// 获取影响行数
result := db.Exec("DELETE FROM logs WHERE created_at < ?", cutoff)
fmt.Println(result.RowsAffected)
```

## Row / Rows（流式读取）

```go
// 单行
var name string
row := db.Raw("SELECT name FROM users WHERE id = ?", 1).Row()
row.Scan(&name)

// 多行（大数据量流式处理，不全量加载内存）
rows, err := db.Raw("SELECT id, name FROM users WHERE status = ?", "active").Rows()
defer rows.Close()
for rows.Next() {
    var id int64
    var name string
    rows.Scan(&id, &name)
    // 逐行处理
}
```

## PreparedStatement 与 Raw SQL

开启 `PrepareStmt: true` 后，Raw SQL 同样会被缓存：

```go
// 第一次执行：编译 SQL
// 后续执行：直接复用 prepared statement
db.Raw("SELECT * FROM users WHERE id = ?", id).Scan(&user)
```

手动使用 prepared statement：

```go
stmt, err := db.DB().PrepareContext(ctx, "SELECT * FROM users WHERE id = ?")
defer stmt.Close()
row := stmt.QueryRowContext(ctx, userID)
```

## Named 参数（可读性更好）

```go
db.Where("name = @name OR email = @email", sql.Named("name", "jinzhu"), sql.Named("email", "jinzhu@example.com")).Find(&users)

// Raw 同样支持
db.Raw("SELECT * FROM users WHERE name = @name", map[string]any{"name": "jinzhu"}).Scan(&users)
```

---

## Find / First / Take / Last 行为差异（v2 重要变化）

### 方法对比

| 方法 | 隐式 ORDER BY | 触发 ErrRecordNotFound | 适用场景 |
|------|-------------|----------------------|---------|
| `First` | `ORDER BY id ASC LIMIT 1` | ✅ 是 | 按主键取第一条 |
| `Last` | `ORDER BY id DESC LIMIT 1` | ✅ 是 | 按主键取最后一条 |
| `Take` | 无 | ✅ 是 | 不需要排序的单条查询（推荐） |
| `Find` | 无 | ❌ 否（返回空切片） | 查询列表 |

```go
// First / Last / Take：找不到时返回 gorm.ErrRecordNotFound
var user User
err := db.Where("id = ?", 999).First(&user).Error
if errors.Is(err, gorm.ErrRecordNotFound) {
    // 正常处理：记录不存在
}

// ❌ v1 的旧写法，v2 中已移除
// if gorm.IsRecordNotFoundError(err) { ... }

// Find：找不到时不报错，返回空切片
var users []User
db.Where("status = ?", 99).Find(&users)
// err == nil，len(users) == 0

// ✅ 按主键查单条，用 Take（无 ORDER BY 开销）
db.Where("id = ?", id).Take(&user)

// ✅ 需要有序取第一条，用 First
db.Where("status = ?", "pending").Order("priority DESC").First(&task)
```

### Error 处理规范（v2）

```go
// ✅ v2 正确写法：errors.Is
if errors.Is(err, gorm.ErrRecordNotFound) { }
if errors.Is(err, gorm.ErrInvalidTransaction) { }
if errors.Is(err, gorm.ErrMissingWhereClause) { }

// ✅ 封装辅助函数，统一处理
func IsNotFound(err error) bool {
    return errors.Is(err, gorm.ErrRecordNotFound)
}

func IgnoreNotFound(err error) error {
    if IsNotFound(err) {
        return nil
    }
    return err
}

// 使用
user, err := userModel.Find(ctx, id)
if err != nil {
    if IsNotFound(err) {
        return nil, ErrUserNotFound // 转换为业务错误
    }
    return nil, err
}
```

# GORM Scopes（可复用查询条件）

> Scope 是将常用查询条件封装为函数，通过 `db.Scopes(...)` 组合调用，避免重复代码。

---

## 1. 基础用法

```go
// 定义 Scope 函数：签名固定为 func(*gorm.DB) *gorm.DB
func ActiveUser(db *gorm.DB) *gorm.DB {
    return db.Where("status = ?", "active")
}

func AgeOver(age int) func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        return db.Where("age > ?", age)
    }
}

func OrderByCreatedDesc(db *gorm.DB) *gorm.DB {
    return db.Order("created_at DESC")
}

// 组合使用
db.Scopes(ActiveUser, AgeOver(18), OrderByCreatedDesc).Find(&users)
// 等价于: WHERE status='active' AND age>18 ORDER BY created_at DESC
```

---

## 2. 分页 Scope（高频通用）

```go
type PageQuery struct {
    Page     int // 从 1 开始
    PageSize int
}

func Paginate(q PageQuery) func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        if q.PageSize <= 0 {
            q.PageSize = 20
        }
        if q.PageSize > 100 {
            q.PageSize = 100 // 防止超大分页
        }
        offset := (q.Page - 1) * q.PageSize
        return db.Offset(offset).Limit(q.PageSize)
    }
}

// 使用
db.Scopes(Paginate(PageQuery{Page: 2, PageSize: 20})).Find(&users)
```

> ⚠️ 大表分页仍需注意 OFFSET 性能，超过万级建议切换游标分页。

---

## 3. 时间范围 Scope

```go
func CreatedBetween(start, end time.Time) func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        return db.Where("created_at BETWEEN ? AND ?", start, end)
    }
}

func LastNDays(n int) func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        return db.Where("created_at >= ?", time.Now().AddDate(0, 0, -n))
    }
}

// 查询最近 7 天的活跃用户
db.Scopes(ActiveUser, LastNDays(7)).Find(&users)
```

---

## 4. 多租户行级隔离 Scope

```go
// 从 context 中提取 tenant_id，自动注入所有查询
func TenantScope(ctx context.Context) func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        tenantID, ok := ctx.Value("tenant_id").(uint)
        if !ok || tenantID == 0 {
            // 没有租户信息时，返回空结果（安全默认）
            return db.Where("1 = 0")
        }
        return db.Where("tenant_id = ?", tenantID)
    }
}

// 在 Service 层统一使用
func (s *OrderService) ListOrders(ctx context.Context) ([]Order, error) {
    var orders []Order
    err := s.db.WithContext(ctx).
        Scopes(TenantScope(ctx), ActiveOrder).
        Find(&orders).Error
    return orders, err
}
```

---

## 5. 软删除相关 Scope

```go
// 只查已删除记录
func OnlyDeleted(db *gorm.DB) *gorm.DB {
    return db.Unscoped().Where("deleted_at IS NOT NULL")
}

// 包含已删除记录（用于管理后台）
func WithDeleted(db *gorm.DB) *gorm.DB {
    return db.Unscoped()
}

// 管理后台查所有（包含软删除）
db.Scopes(WithDeleted).Find(&users)
```

---

## 6. Scope 链式注册（Model 方法风格）

```go
// 推荐：在 Model 上定义领域 Scope，让查询意图更清晰
type Order struct {
    gorm.Model
    UserID uint
    Status string
    Amount int64
}

func (Order) Paid() func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        return db.Where("status = ?", "paid")
    }
}

func (Order) ByUser(userID uint) func(*gorm.DB) *gorm.DB {
    return func(db *gorm.DB) *gorm.DB {
        return db.Where("user_id = ?", userID)
    }
}

// 调用
var o Order
db.Scopes(o.Paid(), o.ByUser(42)).Find(&orders)
```

---

## 7. 常见坑

| 问题 | 说明 | 解决方案 |
|------|------|----------|
| Scope 内修改了原 db 实例 | Scope 函数应 return 新 db，不要赋值给外部变量 | 确保只 return db.Where(...) |
| 分页 Scope 与 Count 冲突 | Count 查询不应带 Limit/Offset | Count 前不要调用 Paginate Scope |
| 多租户 Scope 未覆盖写操作 | Create/Update 时忘记注入 tenant_id | 用 BeforeCreate Hook 或 default tag 补充 |

# GORM v2 Serializer 与自定义数据类型

> GORM v2 提供两种机制将 Go 类型映射到数据库字段：
> Serializer（JSON/Gob/自定义序列化）和 Scanner/Valuer 接口（自定义数据类型）。

---

## 1. 内置 Serializer

### 1.1 JSON Serializer

```go
// gorm:"serializer:json" → 自动 JSON 序列化/反序列化
type User struct {
    gorm.Model
    // ✅ 推荐：直接用 serializer，比 string/datatypes.JSON 更简洁
    Tags      []string          `gorm:"column:tags;type:json;serializer:json"`
    Config    map[string]string `gorm:"column:config;type:json;serializer:json"`
    Address   Address           `gorm:"column:address;type:json;serializer:json"`
}

type Address struct {
    Province string `json:"province"`
    City     string `json:"city"`
    Street   string `json:"street"`
}

// 存储：{"province":"广东","city":"深圳","street":"科技园"}
// 读取：自动反序列化为 Address struct
```

### 1.2 Gob Serializer（二进制，更紧凑）

```go
type Session struct {
    gorm.Model
    // Gob 编码比 JSON 更紧凑，但不可读，适合内部存储
    Data map[string]interface{} `gorm:"column:data;type:blob;serializer:gob"`
}
```

### 1.3 UnixTime Serializer

```go
type Event struct {
    gorm.Model
    // 数据库存 int64 Unix 时间戳，Go 层自动转换为 time.Time
    StartAt time.Time `gorm:"column:start_at;type:bigint;serializer:unixtime"`
    EndAt   time.Time `gorm:"column:end_at;type:bigint;serializer:unixtime"`
}
```

---

## 2. 自定义 Serializer

实现 `schema.SerializerInterface` 接口：

```go
import "gorm.io/gorm/schema"

// 手机号加密 Serializer（存储时加密，读取时解密）
type EncryptedSerializer struct{}

func (EncryptedSerializer) Scan(ctx context.Context, field *schema.Field,
    dst reflect.Value, dbValue interface{}) error {
    // dbValue 是从数据库读到的值（已加密的字符串）
    if encrypted, ok := dbValue.(string); ok {
        decrypted, err := decrypt(encrypted)
        if err != nil {
            return err
        }
        field.ReflectValueOf(ctx, dst).SetString(decrypted)
    }
    return nil
}

func (EncryptedSerializer) Value(ctx context.Context, field *schema.Field,
    dst reflect.Value, fieldValue interface{}) (interface{}, error) {
    // fieldValue 是 Go 层的原始值，加密后存入 DB
    plaintext, ok := fieldValue.(string)
    if !ok || plaintext == "" {
        return plaintext, nil
    }
    return encrypt(plaintext)
}

// 注册到 GORM
func init() {
    schema.RegisterSerializer("encrypted", EncryptedSerializer{})
}

// 使用
type User struct {
    gorm.Model
    Phone  string `gorm:"column:phone;type:varchar(128);serializer:encrypted"`
    IdCard string `gorm:"column:id_card;type:varchar(256);serializer:encrypted"`
}
```

---

## 3. 自定义数据类型（Scanner / Valuer）

实现 `sql.Scanner` 和 `driver.Valuer` 接口，让自定义类型直接映射数据库字段。

### 3.1 枚举类型

```go
// 比 int/string 更类型安全的枚举
type OrderStatus int8

const (
    OrderStatusPending   OrderStatus = 0
    OrderStatusPaid      OrderStatus = 1
    OrderStatusCancelled OrderStatus = 2
)

// driver.Valuer：Go → DB
func (s OrderStatus) Value() (driver.Value, error) {
    return int64(s), nil
}

// sql.Scanner：DB → Go
func (s *OrderStatus) Scan(value interface{}) error {
    if v, ok := value.(int64); ok {
        *s = OrderStatus(v)
        return nil
    }
    return fmt.Errorf("cannot scan %T into OrderStatus", value)
}

// 使用
type Order struct {
    gorm.Model
    Status OrderStatus `gorm:"column:status;type:tinyint;default:0"`
}
// 查询时自动转换为 OrderStatus，无需手动类型断言
```

### 3.2 Money 类型（分→元自动转换）

```go
// 数据库存分（int64），Go 层用浮点表示元
type Money int64 // 单位：分

func (m Money) Yuan() float64 { return float64(m) / 100 }
func (m Money) String() string { return fmt.Sprintf("¥%.2f", m.Yuan()) }

func (m Money) Value() (driver.Value, error) {
    return int64(m), nil
}

func (m *Money) Scan(value interface{}) error {
    if v, ok := value.(int64); ok {
        *m = Money(v)
        return nil
    }
    return fmt.Errorf("cannot scan %T into Money", value)
}

// JSON 序列化为元（方便前端）
func (m Money) MarshalJSON() ([]byte, error) {
    return json.Marshal(m.Yuan())
}

type Order struct {
    gorm.Model
    TotalAmount Money `gorm:"column:total_amount;type:bigint;default:0"`
    // 数据库: 9900  Go: 9900 (分)  JSON: 99.00 (元)
}
```

### 3.3 JSON 字段（替代 datatypes.JSON）

```go
// 比 datatypes.JSON 更类型安全的 JSON 字段
type ExtData struct {
    Source   string `json:"source"`
    Channel  string `json:"channel"`
    Platform string `json:"platform"`
}

func (e ExtData) Value() (driver.Value, error) {
    return json.Marshal(e)
}

func (e *ExtData) Scan(value interface{}) error {
    var data []byte
    switch v := value.(type) {
    case []byte:
        data = v
    case string:
        data = []byte(v)
    default:
        return fmt.Errorf("cannot scan %T into ExtData", value)
    }
    return json.Unmarshal(data, e)
}

type Order struct {
    gorm.Model
    ExtData ExtData `gorm:"column:ext_data;type:json"`
    // 直接访问 order.ExtData.Source，无需 JSON 解析
}
```

---

## 4. GormDataType 接口（自定义列类型）

```go
// 实现 schema.GormDataTypeInterface 让 AutoMigrate 自动使用正确的数据库类型
type JSONArray []string

func (JSONArray) GormDataType() string {
    return "json"
}

func (j JSONArray) Value() (driver.Value, error) {
    return json.Marshal(j)
}

func (j *JSONArray) Scan(value interface{}) error {
    // ...
}

type Tag struct {
    gorm.Model
    Names JSONArray `gorm:"column:names"` // AutoMigrate 自动建 json 类型列
}
```

---

## 5. 选型建议

| 需求 | 推荐方案 |
|------|---------|
| struct/map 存 JSON 列 | `serializer:json` Tag |
| 需要 JSON 字段级查询（JSONQuery） | `datatypes.JSON` |
| 敏感字段加密存储 | 自定义 Serializer |
| 枚举类型映射 | 实现 `Scanner/Valuer` |
| 金额、特殊数值类型 | 实现 `Scanner/Valuer` + `MarshalJSON` |
| 二进制紧凑存储 | `serializer:gob` |
| 时间戳 ↔ time.Time | `serializer:unixtime` 或 `autoCreateTime`/`autoUpdateTime` |

# GORM v2 Session 机制

> Session 是 GORM v2 最核心的设计之一，理解它能避免最常见的条件累积和并发安全问题。

---

## 1. Session 是什么

GORM v2 中 `*gorm.DB` 是**有状态对象**，每次链式调用都会在原有 `Statement` 上追加条件。`Session` 用于创建一个新的独立会话，隔离查询状态。

```go
// ❌ 危险：复用同一个 db 实例多次调用，条件会累积
db = db.Where("status = ?", 1)
db.Find(&list1) // WHERE status=1
db.Find(&list2) // WHERE status=1 AND status=1 ← 条件重复叠加！

// ✅ 正确：每次查询前用 Session 开启新状态
base := db.Where("status = ?", 1)
base.Session(&gorm.Session{NewDB: true}).Find(&list1)
base.Session(&gorm.Session{NewDB: true}).Find(&list2)
```

---

## 2. Session 配置项详解

```go
db.Session(&gorm.Session{
    // NewDB: true → 清除所有已有条件，从干净状态开始（最常用）
    NewDB: true,

    // DryRun: true → 只生成 SQL，不执行（用于调试、预检查）
    DryRun: true,

    // PrepareStmt: true → 开启 PreparedStatement 缓存（推荐生产使用）
    PrepareStmt: true,

    // SkipHooks: true → 跳过 BeforeCreate/AfterUpdate 等所有 Hook
    SkipHooks: true,

    // SkipDefaultTransaction: true → 跳过单条写操作的隐式事务
    SkipDefaultTransaction: true,

    // AllowGlobalUpdate: true → 允许无 WHERE 条件的全表更新/删除（危险！）
    AllowGlobalUpdate: false, // 默认 false，禁止

    // FullSaveAssociations: true → Save 时级联保存所有关联
    FullSaveAssociations: false,

    // Context: ctx → 绑定 context（WithContext 内部就是用这个）
    Context: ctx,

    // Logger: customLogger → 覆盖当前查询的 Logger
    Logger: logger.Default.LogMode(logger.Info),
})
```

---

## 3. NewDB vs WithContext 的区别

```go
// WithContext：只绑定 context，保留已有 WHERE 条件
db.Where("status = 1").WithContext(ctx).Find(&list)
// 等价于: db.Where("status=1").Session(&gorm.Session{Context: ctx}).Find(&list)

// NewDB：清除所有条件，相当于从 db 重新开始
db.Where("status = 1").Session(&gorm.Session{NewDB: true}).Find(&list)
// WHERE 条件被清除，等价于: db.WithContext(ctx).Find(&list)
```

---

## 4. goroutine 安全问题

`*gorm.DB` **不是** goroutine 安全的，多个 goroutine 共享同一个带有累积条件的 `*gorm.DB` 实例会导致数据竞争。

```go
// ❌ 危险：多个 goroutine 共享同一个有状态的 db 实例
baseDB := db.Where("tenant_id = ?", tenantID) // 有状态

for i := 0; i < 10; i++ {
    go func(id int) {
        baseDB.Where("id = ?", id).Find(&result) // 数据竞争！
    }(i)
}

// ✅ 正确方案一：每个 goroutine 用 Session 隔离
baseDB := db.Where("tenant_id = ?", tenantID)

for i := 0; i < 10; i++ {
    go func(id int) {
        // Session(NewDB) 创建独立副本，goroutine 安全
        baseDB.Session(&gorm.Session{NewDB: true}).
            Where("id = ?", id).Find(&result)
    }(i)
}

// ✅ 正确方案二：goroutine 内直接用原始 db 构建完整查询
for i := 0; i < 10; i++ {
    go func(id int) {
        db.Where("tenant_id = ? AND id = ?", tenantID, id).Find(&result)
    }(i)
}
```

---

## 5. DryRun 调试复杂 SQL

```go
// 生成 SQL 但不执行，用于调试复杂查询
stmt := db.Session(&gorm.Session{DryRun: true}).
    Where("tenant_id = ?", tenantID).
    Preload("Orders", "status = ?", "paid").
    Find(&users).Statement

fmt.Println(stmt.SQL.String()) // 打印完整 SQL
fmt.Println(stmt.Vars)         // 打印参数列表

// 也可以用 ToSQL 快捷方式（GORM v2.0+）
sql := db.ToSQL(func(tx *gorm.DB) *gorm.DB {
    return tx.Where("id > ?", 100).Limit(10).Find(&users)
})
fmt.Println(sql)
```

---

## 6. PrepareStmt Session 缓存

```go
// 全局开启（推荐）
db, _ := gorm.Open(mysql.Open(dsn), &gorm.Config{
    PrepareStmt: true,
})

// 针对特定高频查询开启
stmtDB := db.Session(&gorm.Session{PrepareStmt: true})
for i := 0; i < 10000; i++ {
    stmtDB.Where("id = ?", i).Find(&user) // SQL 只编译一次，后续复用
}

// 清除 PreparedStatement 缓存（schema 变更后使用）
stmtManger, ok := db.ConnPool.(*gorm.PreparedStmtDB)
if ok {
    stmtManger.Reset() // 清除所有缓存的 PreparedStatement
}
```

---

## 7. 在 BaseModel 中正确使用 Session

```go
// GetDB 函数（transaction.go 中）用 NewDB Session 是正确的
func GetDB(ctx context.Context, db *gorm.DB) *gorm.DB {
    if tx, ok := ctx.Value(contextTxKey{}).(*gorm.DB); ok {
        return tx // 事务连接不需要 NewDB，直接复用
    }
    // 非事务：NewDB 保证每次查询状态干净
    return db.Session(&gorm.Session{NewDB: true})
}

// Page 中 COUNT 和 Find 复用 baseDB 时，应 Session 隔离
baseDB := db.Where(query, args...)
baseDB.Session(&gorm.Session{}).Count(&total)   // 独立 session
baseDB.Session(&gorm.Session{}).Find(&list)     // 独立 session
// 不能直接: baseDB.Count(&total); baseDB.Find(&list) ← 条件累积
```

---

## 8. 常见 Session 陷阱汇总

| 陷阱 | 现象 | 解决方案 |
|------|------|----------|
| 全局 db 链式累积 | WHERE 条件越来越多 | 每次查询用 `Session{NewDB:true}` 或直接从 db 重新构建 |
| goroutine 共享有状态 db | 数据竞争、结果混乱 | goroutine 内用 `Session{NewDB:true}` 创建独立副本 |
| Page 中 Count+Find 条件污染 | Count 的 GROUP BY 影响 Find | 每次用 `Session{}` 开新 session |
| PrepareStmt schema 变更后报错 | 旧 SQL 缓存与新 schema 不匹配 | `stmtManager.Reset()` 清除缓存 |
| DryRun 全局开启 | 所有写操作静默失效 | DryRun 只在调试时用，或用 `ToSQL` 替代 |

# 软删除（Soft Delete）完整指南

## 1. 基本用法

```go
// 使用 gorm.Model 自动获得 DeletedAt 字段
type User struct {
    gorm.Model
    Name string
}

// 或手动声明（更灵活）
type User struct {
    ID        uint           `gorm:"primaryKey"`
    Name      string
    DeletedAt gorm.DeletedAt `gorm:"index"` // 必须加索引
}
```

### 1.1 Delete = 软删除

```go
db.Delete(&user)
// UPDATE users SET deleted_at='2024-01-01 12:00:00' WHERE id = 1

// 硬删除
db.Unscoped().Delete(&user)
// DELETE FROM users WHERE id = 1
```

### 1.2 查询自动排除已删除

```go
db.Find(&users)
// SELECT * FROM users WHERE deleted_at IS NULL

// 包含已删除的数据
db.Unscoped().Find(&users)
// SELECT * FROM users
```

---

## 2. 软删除 + 唯一约束（经典坑）

### 问题
用户被软删除后，用相同 email 注册会报 `Duplicate entry`：

```go
// users 表有 UNIQUE(email)
db.Delete(&user1)                       // 软删除 email=a@test.com
db.Create(&User{Email: "a@test.com"})  // ❌ Duplicate entry!
```

### 解决方案：复合唯一索引包含 deleted_at

```go
type User struct {
    gorm.Model
    Email     string         `gorm:"size:100;not null"`
    DeletedAt gorm.DeletedAt `gorm:"index"`
}

// 手动建复合唯一索引（AutoMigrate 不支持此功能）
// MySQL:
//   CREATE UNIQUE INDEX uk_users_email ON users(email, deleted_at);
//   -- 注意：MySQL InnoDB 中 NULL 值在唯一索引中不冲突，
//   -- 所以 deleted_at IS NULL 的记录可以保持 email 唯一性
//
// PostgreSQL:
//   CREATE UNIQUE INDEX uk_users_email ON users(email) WHERE deleted_at IS NULL;
//   -- 部分索引，更精确
```

### 替代方案：软删除时修改唯一字段

```go
// Hook: 软删除时给唯一字段追加删除标记
func (u *User) BeforeDelete(tx *gorm.DB) error {
    return tx.Model(u).Update("email",
        fmt.Sprintf("%s__deleted_%d", u.Email, time.Now().UnixNano())).Error
}
```

---

## 3. 软删除 + Preload

```go
// 默认: Preload 也会自动排除已软删除的关联
db.Preload("Orders").Find(&users)
// Orders 中已删除的订单不会加载

// 包含已软删除的关联
db.Preload("Orders", func(db *gorm.DB) *gorm.DB {
    return db.Unscoped()
}).Find(&users)
```

---

## 4. 使用 Unix 时间戳作为软删除标记

```go
import "gorm.io/plugin/soft_delete"

type User struct {
    ID        uint
    Name      string
    DeletedAt soft_delete.DeletedAt `gorm:"softDelete:milli"` // 毫秒时间戳
    // DeletedAt soft_delete.DeletedAt                        // 秒时间戳
}
// 未删除: deleted_at = 0
// 已删除: deleted_at = 1704067200000

// 使用 flag 模式（0/1）
type User struct {
    ID      uint
    IsDel   soft_delete.DeletedAt `gorm:"softDelete:flag"`
}
// 未删除: is_del = 0，已删除: is_del = 1
```

### 时间戳模式 vs DeletedAt 的优势

| 特性 | gorm.DeletedAt (NULL) | soft_delete (时间戳/flag) |
|------|----------------------|--------------------------|
| 唯一约束兼容 | MySQL 需要复合索引 | 天然兼容（0 值唯一） |
| 索引效率 | IS NULL 条件 | 等值条件（= 0） |
| 分区表兼容 | 不友好 | 友好 |

---

## 5. 测试中的软删除陷阱

```go
// ❌ 测试中忘记 Unscoped，导致断言失败
db.Delete(&user)
var found User
err := db.First(&found, user.ID).Error
// err = gorm.ErrRecordNotFound（符合预期，但容易迷惑）

// ✅ 测试验证软删除是否生效
db.Delete(&user)
var found User
err := db.Unscoped().First(&found, user.ID).Error
assert.NoError(t, err)
assert.NotNil(t, found.DeletedAt)
```

---

## 6. 性能注意事项

1. **必须给 deleted_at 加索引**：所有查询都会自动加 `WHERE deleted_at IS NULL`
2. **大量软删除数据时**：考虑定期清理（归档到历史表 + 硬删除）
3. **COUNT 查询**：软删除数据越多，`COUNT` 越慢（需扫描更多行判断 IS NULL）

```go
// 定期归档清理（建议通过定时任务执行）
// 1. 将 30 天前软删除的数据归档
db.Unscoped().Where("deleted_at < ?", time.Now().AddDate(0, 0, -30)).
    FindInBatches(&batch, 500, func(tx *gorm.DB, n int) error {
        archiveDB.Create(&batch)  // 写入归档表
        return nil
    })
// 2. 硬删除已归档数据
db.Unscoped().Where("deleted_at < ?", time.Now().AddDate(0, 0, -30)).
    Delete(&User{})
```

#!/usr/bin/env python3
"""
bench_template.py — 为 GORM 函数生成 Go benchmark + pprof 启动代码
用法:
  python3 bench_template.py --func "GetUserByID(db *gorm.DB, id uint) (*User, error)"
  python3 bench_template.py --func "CreateOrder" --package service --file order_service.go
  python3 bench_template.py --scenario bulk_insert --table orders --batch 500

磁盘写入：默认输出到 stdout，仅在用户传 --output <file> 时写磁盘。
外部依赖：无（纯标准库，不调用任何 API）。
"""

import argparse
import re
import sys
from typing import Optional
from datetime import datetime

# ── 场景模板库 ───────────────────────────────────────────────────────────────
SCENARIO_TEMPLATES = {
    "query_by_id": {
        "desc": "主键查询性能",
        "setup": """
    // 预插入测试数据
    users := make([]User, 100)
    for i := range users {
        users[i] = User{Name: fmt.Sprintf("user_%d", i), Email: fmt.Sprintf("u%d@test.com", i)}
    }
    db.CreateInBatches(&users, 50)
    testID := users[0].ID""",
        "bench_body": """
    b.ResetTimer()
    for i := 0; i < b.N; i++ {
        var u User
        db.First(&u, testID)
    }""",
    },

    "query_with_preload": {
        "desc": "Preload 关联查询性能",
        "setup": """
    // 预插入用户和订单
    user := User{Name: "bench_user"}
    db.Create(&user)
    orders := make([]Order, 20)
    for i := range orders {
        orders[i] = Order{UserID: user.ID, Amount: int64(i * 100)}
    }
    db.CreateInBatches(&orders, 20)
    testID := user.ID""",
        "bench_body": """
    b.ResetTimer()
    for i := 0; i < b.N; i++ {
        var u User
        db.Preload("Orders").First(&u, testID)
    }""",
    },

    "bulk_insert": {
        "desc": "批量插入性能",
        "setup": "    batchSize := {batch}",
        "bench_body": """
    b.ResetTimer()
    for i := 0; i < b.N; i++ {
        b.StopTimer()
        records := make([]User, batchSize)
        for j := range records {
            records[j] = User{Name: fmt.Sprintf("u_%d_%d", i, j)}
        }
        b.StartTimer()
        db.CreateInBatches(&records, batchSize)
    }""",
    },

    "pagination": {
        "desc": "游标分页 vs OFFSET 对比",
        "setup": """
    // 插入 10000 条测试数据
    total := 10000
    for i := 0; i < total; i += 500 {
        batch := make([]User, 500)
        for j := range batch {
            batch[j] = User{Name: fmt.Sprintf("user_%d", i+j)}
        }
        db.CreateInBatches(&batch, 500)
    }""",
        "bench_body": """
    b.Run("CursorPagination", func(b *testing.B) {
        b.ResetTimer()
        for i := 0; i < b.N; i++ {
            var users []User
            db.Where("id > ?", 5000).Order("id").Limit(20).Find(&users)
        }
    })

    b.Run("OffsetPagination", func(b *testing.B) {
        b.ResetTimer()
        for i := 0; i < b.N; i++ {
            var users []User
            db.Offset(5000).Limit(20).Find(&users)
        }
    })""",
    },

    "update_compare": {
        "desc": "Save vs Updates(map) vs Update(单字段) 对比",
        "setup": """
    user := User{Name: "bench", Email: "bench@test.com"}
    db.Create(&user)""",
        "bench_body": """
    b.Run("Save_FullStruct", func(b *testing.B) {
        b.ResetTimer()
        for i := 0; i < b.N; i++ {
            user.Name = fmt.Sprintf("name_%d", i)
            db.Save(&user)
        }
    })

    b.Run("Updates_Map", func(b *testing.B) {
        b.ResetTimer()
        for i := 0; i < b.N; i++ {
            db.Model(&user).Updates(map[string]any{"name": fmt.Sprintf("name_%d", i)})
        }
    })

    b.Run("Update_SingleField", func(b *testing.B) {
        b.ResetTimer()
        for i := 0; i < b.N; i++ {
            db.Model(&user).Update("name", fmt.Sprintf("name_%d", i))
        }
    })""",
    },
}


def generate_custom_bench(func_sig: str, package: str) -> str:
    """根据函数签名生成 benchmark"""
    # 解析函数名
    func_name_m = re.match(r'(\w+)', func_sig.strip())
    func_name = func_name_m.group(1) if func_name_m else "TargetFunc"

    # 解析参数
    params_m = re.search(r'\(([^)]*)\)', func_sig)
    params_str = params_m.group(1) if params_m else ""
    params = [p.strip() for p in params_str.split(',') if p.strip()]

    # 构建调用参数
    call_args = []
    setup_lines = []
    for p in params:
        parts = p.split()
        if len(parts) < 2:
            continue
        pname, ptype = parts[0], parts[-1]
        if "gorm.DB" in ptype:
            call_args.append(pname)
        elif ptype in ("uint", "int", "int64", "uint64"):
            setup_lines.append(f"\tvar {pname} {ptype} = 1  // TODO: 设置测试 ID")
            call_args.append(pname)
        elif ptype == "string":
            setup_lines.append(f'\t{pname} := "test_value"  // TODO: 设置测试参数')
            call_args.append(pname)
        else:
            setup_lines.append(f"\tvar {pname} {ptype}  // TODO: 初始化测试数据")
            call_args.append(pname)

    setup_code = "\n".join(setup_lines) if setup_lines else "\t// TODO: 初始化测试数据"
    call_code = f'{package}.{func_name}({", ".join(call_args)})' if package else f'{func_name}({", ".join(call_args)})'

    return f'''func Benchmark{func_name}(b *testing.B) {{
    db := setupBenchDB(b)

{setup_code}

    b.ResetTimer()
    b.ReportAllocs()  // 报告内存分配次数
    for i := 0; i < b.N; i++ {{
        result, err := {call_code}
        if err != nil {{
            b.Fatal(err)
        }}
        _ = result
    }}
}}'''


def generate_full_file(
    package: str,
    func_sig: Optional[str],
    scenario: Optional[str],
    table: str,
    batch: int,
) -> str:
    now = datetime.now().strftime("%Y-%m-%d")

    benchmarks = []
    if func_sig:
        benchmarks.append(generate_custom_bench(func_sig, ""))

    if scenario and scenario in SCENARIO_TEMPLATES:
        tmpl = SCENARIO_TEMPLATES[scenario]
        setup = tmpl["setup"].replace("{batch}", str(batch))
        bench_body = tmpl["bench_body"]
        func_name = "".join(w.capitalize() for w in scenario.split("_"))
        benchmarks.append(f'''// Benchmark{func_name} — {tmpl["desc"]}
func Benchmark{func_name}(b *testing.B) {{
    db := setupBenchDB(b)
{setup}

{bench_body}
}}''')

    bench_code = "\n\n".join(benchmarks) if benchmarks else '''func BenchmarkYourFunction(b *testing.B) {
    db := setupBenchDB(b)
    // TODO: 添加测试数据
    b.ResetTimer()
    b.ReportAllocs()
    for i := 0; i < b.N; i++ {
        // TODO: 调用被测函数
    }
}'''

    return f'''// Code generated by bench_template.py on {now}
// 运行: go test -bench=. -benchmem -count=3 -cpuprofile=cpu.prof -memprofile=mem.prof
// 分析: go tool pprof -http=:8080 cpu.prof
package {package}

import (
\t"fmt"
\t"os"
\t"runtime/pprof"
\t"testing"

\t"gorm.io/driver/sqlite"
\t"gorm.io/gorm"
\t"gorm.io/gorm/logger"
)

// setupBenchDB 创建内存 SQLite DB（快速，适合基准测试）
// 如需测试 MySQL 真实性能，替换为 mysql.Open(dsn)
func setupBenchDB(b *testing.B) *gorm.DB {{
\tb.Helper()
\tdb, err := gorm.Open(sqlite.Open(":memory:"), &gorm.Config{{
\t\tLogger:                 logger.Default.LogMode(logger.Silent),
\t\tSkipDefaultTransaction: true,
\t\tPrepareStmt:            true,
\t}})
\tif err != nil {{
\t\tb.Fatal("setupBenchDB:", err)
\t}}
\t// 迁移你的 Model
\t// db.AutoMigrate(&User{{}}, &Order{{}})

\tb.Cleanup(func() {{
\t\tsqlDB, _ := db.DB()
\t\tsqlDB.Close()
\t}})
\treturn db
}}

// BenchmarkMain 启动 pprof 采集（可选，需要时取消注释）
func BenchmarkMain(m *testing.M) {{
\t// CPU profile
\tcpuF, _ := os.Create("cpu.prof")
\tpprof.StartCPUProfile(cpuF)
\tdefer pprof.StopCPUProfile()

\tcode := m.Run()

\t// Memory profile
\tmemF, _ := os.Create("mem.prof")
\tpprof.WriteHeapProfile(memF)
\tmemF.Close()

\tos.Exit(code)
}}

{bench_code}
'''


def print_usage_tips(scenario: Optional[str], func_name: str) -> None:
    print("\n" + "─" * 60)
    print("📋 使用说明:")
    print()
    print("  # 运行 benchmark（-count=3 减少噪声，-benchtime=3s 延长采样）")
    print(f"  go test -bench=Benchmark{func_name} -benchmem -count=3 -benchtime=3s ./...")
    print()
    print("  # 同时采集 CPU / 内存 profile")
    print(f"  go test -bench=Benchmark{func_name} -benchmem \\")
    print("    -cpuprofile=cpu.prof -memprofile=mem.prof ./...")
    print()
    print("  # 可视化分析（浏览器打开火焰图）")
    print("  go tool pprof -http=:8080 cpu.prof")
    print("  go tool pprof -http=:8081 mem.prof")
    print()
    print("  # 对比两次结果（需要 benchstat）")
    print("  go install golang.org/x/perf/cmd/benchstat@latest")
    print("  go test -bench=. -count=10 > old.txt")
    print("  # ... 修改代码 ...")
    print("  go test -bench=. -count=10 > new.txt")
    print("  benchstat old.txt new.txt")
    print("─" * 60)


def main():
    parser = argparse.ArgumentParser(description="GORM Benchmark + pprof 模板生成器")
    parser.add_argument("--func", dest="func_sig", help="函数签名，如 'GetUser(db *gorm.DB, id uint) (*User, error)'")
    parser.add_argument("--scenario", choices=list(SCENARIO_TEMPLATES.keys()),
                        help=f"预设场景: {', '.join(SCENARIO_TEMPLATES.keys())}")
    parser.add_argument("--package", default="repository_test", help="Go package 名（默认 repository_test）")
    parser.add_argument("--table", default="users", help="主要测试表名（默认 users）")
    parser.add_argument("--batch", type=int, default=500, help="批量操作大小（默认 500）")
    parser.add_argument("--output", default="-", help="输出文件路径（默认 stdout）")
    args = parser.parse_args()

    if not args.func_sig and not args.scenario:
        parser.print_help()
        print("\n示例:")
        print('  python3 bench_template.py --func "GetUserByID(db *gorm.DB, id uint) (*User, error)"')
        print("  python3 bench_template.py --scenario bulk_insert --batch 200")
        print("  python3 bench_template.py --scenario pagination")
        sys.exit(1)

    code = generate_full_file(
        package=args.package,
        func_sig=args.func_sig,
        scenario=args.scenario,
        table=args.table,
        batch=args.batch,
    )

    if args.output == "-":
        print(code)
    else:
        with open(args.output, "w", encoding="utf-8") as f:
            f.write(code)
        print(f"✅ 已生成: {args.output}")

    # 提取函数名用于提示
    func_name = "YourFunction"
    if args.func_sig:
        m = re.match(r'(\w+)', args.func_sig)
        if m:
            func_name = m.group(1)
    elif args.scenario:
        func_name = "".join(w.capitalize() for w in args.scenario.split("_"))

    print_usage_tips(args.scenario, func_name)



if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
pool_advisor.py — 根据业务参数计算推荐的 GORM / database/sql 连接池配置
用法:
  python3 pool_advisor.py \
    --qps 500 \
    --avg-latency-ms 20 \
    --db-max-conn 200 \
    --app-instances 4 \
    --db-type mysql

输出: 直接可粘贴的 Go 配置代码 + 参数说明
"""

import argparse
import math
import sys

def calculate_pool(
    qps: float,
    avg_latency_ms: float,
    db_max_conn: int,
    app_instances: int,
    db_type: str,
    peak_multiplier: float,
    idle_ratio: float,
    conn_lifetime_min: int,
) -> dict:
    """
    核心公式:
      - 理论最小连接数 = QPS × (avg_latency_ms / 1000)  — Little's Law
      - 考虑峰值 × peak_multiplier
      - 每实例最大连接 = min(理论值, db_max_conn / app_instances × 0.8)
      - 空闲连接 = MaxOpen × idle_ratio
    """
    # 基于 Little's Law 的理论值
    theoretical_min = qps * (avg_latency_ms / 1000.0)
    theoretical_with_peak = theoretical_min * peak_multiplier

    # DB 侧每实例允许的上限（留 20% 给管理连接 / 其他工具）
    db_limit_per_instance = math.floor((db_max_conn * 0.8) / app_instances)

    # 最终推荐值
    recommended_max = min(math.ceil(theoretical_with_peak), db_limit_per_instance)
    recommended_max = max(recommended_max, 5)  # 最少 5

    recommended_idle = max(math.ceil(recommended_max * idle_ratio), 2)

    # 连接存活时间：MySQL 默认 8h wait_timeout，建议设置为 < wait_timeout 的 80%
    lifetime_s = conn_lifetime_min * 60
    idle_time_s = max(lifetime_s // 6, 60)  # 空闲连接更激进回收

    return {
        "max_open": recommended_max,
        "max_idle": recommended_idle,
        "conn_lifetime_s": lifetime_s,
        "conn_idle_timeout_s": idle_time_s,
        "theoretical_min": round(theoretical_min, 1),
        "theoretical_peak": round(theoretical_with_peak, 1),
        "db_limit_per_instance": db_limit_per_instance,
        "db_type": db_type,
    }


def render_go_code(r: dict, args) -> str:
    """生成可直接使用的 Go 配置代码"""
    code = f'''// ── GORM 连接池推荐配置 ─────────────────────────────────────────────────────
// 输入参数:
//   QPS: {args.qps}  |  平均延迟: {args.avg_latency_ms}ms
//   DB最大连接: {args.db_max_conn}  |  应用实例数: {args.app_instances}
//   峰值倍数: {args.peak_multiplier}x  |  DB类型: {args.db_type}
//
// 计算过程:
//   理论最小 (Little's Law): {r["theoretical_min"]} 个连接
//   峰值估算 ({args.peak_multiplier}x):  {r["theoretical_peak"]} 个连接
//   DB侧每实例上限:         {r["db_limit_per_instance"]} 个连接
// ─────────────────────────────────────────────────────────────────────────────

sqlDB, err := db.DB()
if err != nil {{
    panic(err)
}}

sqlDB.SetMaxOpenConns({r["max_open"]})                                  // 最大连接数
sqlDB.SetMaxIdleConns({r["max_idle"]})                                   // 空闲连接池 (~{round(args.idle_ratio*100)}% of MaxOpen)
sqlDB.SetConnMaxLifetime({r["conn_lifetime_s"]} * time.Second)          // 连接存活 {args.conn_lifetime_min}min，防 DB 侧主动断开
sqlDB.SetConnMaxIdleTime({r["conn_idle_timeout_s"]} * time.Second)      // 空闲连接 {r["conn_idle_timeout_s"]//60}min 后回收
'''

    # 特定数据库建议
    warnings = []
    if args.db_type == "mysql":
        code += f'''
// MySQL 额外建议:
// 1. 确认 wait_timeout >= {args.conn_lifetime_min * 60 + 300}s (比 ConnMaxLifetime 多 5min)
//    SHOW VARIABLES LIKE 'wait_timeout';
//    SET GLOBAL wait_timeout = {max(args.conn_lifetime_min * 60 + 300, 3600)};
// 2. 开启 interpolateParams=true 减少 round-trip (简单场景):
//    dsn += "&interpolateParams=true"
// 3. 连接串加超时保护:
//    dsn += "&timeout=5s&readTimeout=30s&writeTimeout=30s"
'''
    elif args.db_type == "postgres":
        code += f'''
// PostgreSQL 额外建议:
// 1. pg 默认 max_connections=100，确认: SHOW max_connections;
// 2. 使用 pgBouncer 做连接池代理可大幅提升连接复用率
// 3. DSN 加超时: "connect_timeout=5 statement_timeout=30000"
'''
    elif args.db_type == "sqlite":
        code += '''
// SQLite 注意:
// SQLite 是单写模式，MaxOpenConns 应设为 1（写）+ N（读，WAL模式下）
// WAL 模式下读写可并行:
//   db.Exec("PRAGMA journal_mode=WAL")
sqlDB.SetMaxOpenConns(1)   // 覆盖上面的值，SQLite 写操作串行
'''

    # 健康检查代码
    code += '''
// 连接池健康监控（可接入 Prometheus）
go func() {
    ticker := time.NewTicker(30 * time.Second)
    for range ticker.C {
        stats := sqlDB.Stats()
        log.Printf("DB pool: open=%d idle=%d inUse=%d waitCount=%d",
            stats.OpenConnections,
            stats.Idle,
            stats.InUse,
            stats.WaitCount,
        )
        // 告警条件: InUse 持续接近 MaxOpenConns
        if stats.InUse >= stats.MaxOpenConnections*9/10 {
            log.Warn("DB connection pool near capacity!")
        }
    }
}()
'''

    # 调优建议
    tips = []
    if r["max_open"] == r["db_limit_per_instance"]:
        tips.append(f"⚠️  连接数受 DB 侧限制（{r['db_limit_per_instance']}），理论需求更高。建议扩容 DB max_connections 或增加只读副本")
    if r["theoretical_peak"] > r["db_limit_per_instance"] * 1.5:
        tips.append(f"🔴 峰值需求 ({r['theoretical_peak']}) 远超 DB 侧限制，强烈建议添加读写分离 + 缓存层")
    if args.avg_latency_ms > 100:
        tips.append(f"🟡 平均延迟 {args.avg_latency_ms}ms 偏高，先排查慢 SQL（开启 SlowThreshold=100ms 日志），再做连接池调优")
    if args.app_instances == 1:
        tips.append("ℹ️  当前单实例部署，上线后水平扩展时需同步调小每实例 MaxOpenConns")

    if tips:
        code += "\n// ── 调优建议 ──────────────────────────────────────────────\n"
        for tip in tips:
            code += f"// {tip}\n"

    return code



def render_health_check(result: dict) -> str:
    """生成连接池健康检查代码模板"""
    return f"""
// ── 连接池健康检查（自动生成）──────────────────────────────────────
// 建议将以下代码集成到 /health 端点和定时监控任务中

func DBHealthCheck(db *gorm.DB) error {{
\tsqlDB, err := db.DB()
\tif err != nil {{
\t\treturn fmt.Errorf("get sql.DB failed: %w", err)
\t}}
\tctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
\tdefer cancel()
\treturn sqlDB.PingContext(ctx)
}}

// 定时打印连接池指标（建议每 30s 执行一次）
func StartPoolMonitor(db *gorm.DB, interval time.Duration) {{
\tgo func() {{
\t\tticker := time.NewTicker(interval)
\t\tfor range ticker.C {{
\t\t\tsqlDB, _ := db.DB()
\t\t\tstats := sqlDB.Stats()
\t\t\t// 连接池使用率告警阈值: {int(result['max_open'] * 0.9)} (90% of MaxOpen={result['max_open']})
\t\t\tif stats.InUse >= {int(result['max_open'] * 0.9)} {{
\t\t\t\tlog.Warn("db pool near exhaustion",
\t\t\t\t\t"in_use", stats.InUse, "max_open", {result['max_open']})
\t\t\t}}
\t\t\tlog.Debug("db pool stats",
\t\t\t\t"open", stats.OpenConnections,
\t\t\t\t"in_use", stats.InUse,
\t\t\t\t"idle", stats.Idle,
\t\t\t\t"wait_count", stats.WaitCount,
\t\t\t\t"wait_duration", stats.WaitDuration,
\t\t\t)
\t\t}}
\t}}()
}}
"""

def main():
    parser = argparse.ArgumentParser(description="GORM 连接池参数顾问")
    parser.add_argument("--qps", type=float, required=True, help="目标 QPS（数据库操作次数/秒）")
    parser.add_argument("--avg-latency-ms", type=float, default=20, help="平均 DB 操作延迟 ms（默认 20）")
    parser.add_argument("--db-max-conn", type=int, default=200, help="DB 服务器最大连接数（默认 200）")
    parser.add_argument("--app-instances", type=int, default=1, help="应用实例数（默认 1）")
    parser.add_argument("--db-type", choices=["mysql", "postgres", "sqlite"], default="mysql")
    parser.add_argument("--peak-multiplier", type=float, default=2.0, help="峰值倍数（默认 2x）")
    parser.add_argument("--idle-ratio", type=float, default=0.25, help="空闲连接比例（默认 0.25）")
    parser.add_argument("--conn-lifetime-min", type=int, default=60, help="连接最大存活分钟数（默认 60）")

    args = parser.parse_args()

    if args.qps <= 0:
        print("❌ QPS 必须大于 0", file=sys.stderr)
        sys.exit(1)
    if args.avg_latency_ms <= 0:
        print("❌ avg-latency-ms 必须大于 0", file=sys.stderr)
        sys.exit(1)

    result = calculate_pool(
        qps=args.qps,
        avg_latency_ms=args.avg_latency_ms,
        db_max_conn=args.db_max_conn,
        app_instances=args.app_instances,
        db_type=args.db_type,
        peak_multiplier=args.peak_multiplier,
        idle_ratio=args.idle_ratio,
        conn_lifetime_min=args.conn_lifetime_min,
    )

    print(render_go_code(result, args))
    print(render_health_check(result))

    # 打印摘要表
    print("// ── 参数摘要 ───────────────────────────────────────────────")
    print(f"// MaxOpenConns      = {result['max_open']}")
    print(f"// MaxIdleConns      = {result['max_idle']}")
    print(f"// ConnMaxLifetime   = {result['conn_lifetime_s']}s")
    print(f"// ConnMaxIdleTime   = {result['conn_idle_timeout_s']}s")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
scope_gen.py — 根据 GORM struct 字段自动生成常用 Scope 函数模板
用法:
  python3 scope_gen.py model.go
  cat model.go | python3 scope_gen.py -
  python3 scope_gen.py model.go --tenant   # 额外生成多租户 Scope
  python3 scope_gen.py model.go --paginate # 额外生成分页 Scope
"""

import sys
import re
import argparse
from dataclasses import dataclass
from typing import List, Optional

@dataclass
class Field:
    name: str        # Go 字段名，如 Status
    go_type: str     # Go 类型，如 string / uint / time.Time
    col_name: str    # 数据库列名（snake_case），如 status

# ── snake_case 转换 ──────────────────────────────────────────────────────────
def to_snake(name: str) -> str:
    s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', name)
    s = re.sub(r'([a-z\d])([A-Z])', r'\1_\2', s)
    return s.lower()

# ── 从 Go struct 提取字段 ────────────────────────────────────────────────────
def parse_struct(code: str) -> List[tuple]:
    """返回 [(struct_name, [Field]), ...]"""
    results = []
    # 匹配 type XxxStruct struct { ... }
    struct_pat = re.compile(
        r'type\s+(\w+)\s+struct\s*\{([^}]+)\}', re.DOTALL)
    for m in struct_pat.finditer(code):
        struct_name = m.group(1)
        body = m.group(2)
        fields = []
        for line in body.splitlines():
            line = line.strip()
            if not line or line.startswith("//"):
                continue
            # 跳过嵌入类型（gorm.Model 等）
            if re.match(r'^[a-z]', line) or re.match(r'^\w+\.\w+$', line.split()[0] if line.split() else ''):
                continue
            parts = line.split()
            if len(parts) < 2:
                continue
            fname = parts[0]
            ftype = parts[1]
            # 从 gorm tag 提取 column 名
            col_match = re.search(r'gorm:"[^"]*column:(\w+)', line)
            col_name = col_match.group(1) if col_match else to_snake(fname)
            fields.append(Field(name=fname, go_type=ftype, col_name=col_name))
        if fields:
            results.append((struct_name, fields))
    return results

# ── 生成等值查询 Scope ────────────────────────────────────────────────────────
def gen_eq_scope(struct_name: str, f: Field) -> Optional[str]:
    """WHERE col = ? 类型的 Scope"""
    receiver = struct_name[0].lower()
    param = f.name[0].lower() + f.name[1:]
    return (
        f"// {struct_name}By{f.name} 按 {f.col_name} 精确匹配\n"
        f"func ({receiver} {struct_name}) By{f.name}(val {f.go_type}) func(*gorm.DB) *gorm.DB {{\n"
        f'\treturn func(db *gorm.DB) *gorm.DB {{\n'
        f'\t\treturn db.Where("{f.col_name} = ?", val)\n'
        f'\t}}\n'
        f'}}'
    )

# ── 生成范围查询 Scope（数字/时间字段）──────────────────────────────────────
def gen_range_scope(struct_name: str, f: Field) -> Optional[str]:
    receiver = struct_name[0].lower()
    numeric_types = {"int", "int8", "int16", "int32", "int64",
                     "uint", "uint8", "uint16", "uint32", "uint64",
                     "float32", "float64"}
    if f.go_type not in numeric_types and "time.Time" not in f.go_type:
        return None
    return (
        f"// {struct_name}{f.name}Between 按 {f.col_name} 范围查询\n"
        f"func ({receiver} {struct_name}) {f.name}Between(from, to {f.go_type}) func(*gorm.DB) *gorm.DB {{\n"
        f'\treturn func(db *gorm.DB) *gorm.DB {{\n'
        f'\t\treturn db.Where("{f.col_name} BETWEEN ? AND ?", from, to)\n'
        f'\t}}\n'
        f'}}'
    )

# ── 生成 IN 查询 Scope ────────────────────────────────────────────────────────
def gen_in_scope(struct_name: str, f: Field) -> str:
    receiver = struct_name[0].lower()
    return (
        f"// {struct_name}{f.name}In 按 {f.col_name} IN 批量查询\n"
        f"func ({receiver} {struct_name}) {f.name}In(vals ...{f.go_type}) func(*gorm.DB) *gorm.DB {{\n"
        f'\treturn func(db *gorm.DB) *gorm.DB {{\n'
        f'\t\treturn db.Where("{f.col_name} IN ?", vals)\n'
        f'\t}}\n'
        f'}}'
    )

# ── 生成分页 Scope ────────────────────────────────────────────────────────────
PAGINATE_SCOPE = '''\
// Paginate 通用分页 Scope（Page 从 1 开始）
type PageQuery struct {
\tPage     int
\tPageSize int
}

func Paginate(q PageQuery) func(*gorm.DB) *gorm.DB {
\treturn func(db *gorm.DB) *gorm.DB {
\t\tif q.PageSize <= 0 {
\t\t\tq.PageSize = 20
\t\t}
\t\tif q.PageSize > 200 {
\t\t\tq.PageSize = 200
\t\t}
\t\toffset := (q.Page - 1) * q.PageSize
\t\treturn db.Offset(offset).Limit(q.PageSize)
\t}
}'''

# ── 生成多租户 Scope ─────────────────────────────────────────────────────────
TENANT_SCOPE = '''\
// TenantScope 多租户行级隔离 Scope（从 context 中读取 tenant_id）
func TenantScope(ctx context.Context) func(*gorm.DB) *gorm.DB {
\treturn func(db *gorm.DB) *gorm.DB {
\t\ttenantID, ok := ctx.Value("tenant_id").(uint)
\t\tif !ok || tenantID == 0 {
\t\t\treturn db.Where("1 = 0") // 无租户信息时拒绝访问
\t\t}
\t\treturn db.Where("tenant_id = ?", tenantID)
\t}
}'''

# ── 决定哪些字段需要生成 Scope ───────────────────────────────────────────────
SKIP_FIELDS = {"ID", "CreatedAt", "UpdatedAt", "DeletedAt", "Password",
               "Salt", "Token", "Secret"}
ENUM_LIKE = {"Status", "Type", "State", "Role", "Kind", "Category"}

def should_generate(f: Field) -> bool:
    if f.name in SKIP_FIELDS:
        return False
    if f.go_type in ("[]byte", "datatypes.JSON"):
        return False
    return True

# ── 主函数 ────────────────────────────────────────────────────────────────────
def generate(code: str, with_tenant: bool, with_paginate: bool) -> str:
    structs = parse_struct(code)
    if not structs:
        return "// ⚠️ 未找到 Go struct 定义，请检查输入内容\n"

    lines = [
        "package model",
        "",
        'import "gorm.io/gorm"',
        "",
    ]
    if with_tenant:
        lines += ['import "context"', ""]
    lines += ["// ── 自动生成的 Scope 函数（scope_gen.py）─────────────────────", ""]

    if with_paginate:
        lines += [PAGINATE_SCOPE, ""]

    if with_tenant:
        lines += [TENANT_SCOPE, ""]

    for struct_name, fields in structs:
        lines.append(f"// ── {struct_name} Scopes ────────────────────────────────────")
        for f in fields:
            if not should_generate(f):
                continue
            # 等值查询
            lines.append(gen_eq_scope(struct_name, f))
            lines.append("")
            # IN 查询（枚举/ID 类字段）
            if f.name in ENUM_LIKE or f.go_type in ("uint", "uint64", "int64", "string"):
                lines.append(gen_in_scope(struct_name, f))
                lines.append("")
            # 范围查询（数字/时间）
            r = gen_range_scope(struct_name, f)
            if r:
                lines.append(r)
                lines.append("")

    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="GORM Scope 生成器")
    parser.add_argument("file", nargs="?", default="-",
                        help="Go 文件路径，- 表示 stdin")
    parser.add_argument("--tenant", action="store_true",
                        help="生成多租户 TenantScope")
    parser.add_argument("--paginate", action="store_true",
                        help="生成分页 Paginate Scope")
    args = parser.parse_args()

    if args.file == "-":
        code = sys.stdin.read()
    else:
        with open(args.file, "r", encoding="utf-8") as f:
            code = f.read()

    print(generate(code, with_tenant=args.tenant, with_paginate=args.paginate))


if __name__ == "__main__":
    main()
